SELECT $q$Garmin Forerunner 265 – GPS running watch$q$, $q$garmin-forerunner-265-gps-running-watch$q$, $q$The Garmin Forerunner 265 is a GPS running watch with a 1.3-inch (32.5 mm) AMOLED touchscreen. Its 46.1 × 46.1 × 12.9 mm case is controlled by touch or with the physical buttons.

On performance: multi-band GPS with SatIQ™, up to 13 days of battery life in smartwatch mode and up to 20 hours in GPS-only mode. It offers daily suggested workouts, a race predictor, training load, wrist-based running dynamics, recovery time and a sleep coach.

Compared with the previous generation (Forerunner 255), it moves to an AMOLED touchscreen and multi-band GPS. Day to day, it tracks wrist-based heart rate, Body Battery™, stress, breathwork, hydration, women’s health and naps. Warranty as stated in the offer.$q$, NULL, NULL, $q$https://www.aliexpress.com/item/1005006037883124.html$q$, $q$https://ae-pic-a1.aliexpress-media.com/kf/Sf6415d7329334104a99a2ac5b9ea2480Q.jpg$q$,
  ARRAY[$q$https://ae-pic-a1.aliexpress-media.com/kf/Sf6415d7329334104a99a2ac5b9ea2480Q.jpg$q$, $q$https://ae-pic-a1.aliexpress-media.com/kf/Sb74dcc665d1f46ff975bbaf824a1fbe3o.jpg$q$, $q$https://ae-pic-a1.aliexpress-media.com/kf/S812dfdf60760498da7bd2435b086e1a9C.jpg$q$, $q$https://ae-pic-a1.aliexpress-media.com/kf/Sdd4b83ab148f4e23b2d64aa1385fd981D.jpg$q$, $q$https://ae-pic-a1.aliexpress-media.com/kf/Sce936179e1ce431186b2d3df46ae65b7y.jpg$q$]::text[], false,
  $q$Garmin Forerunner 265: the AMOLED GPS running watch$q$, $q$Touchscreen AMOLED display, multi-band GPS and recovery tracking: a complete running watch for training with purpose.$q$, '[]'::jsonb, $j$[{"icon": "⌚", "title": "1.3\" AMOLED touchscreen with buttons", "description": "A 32.5 mm colour display, controlled by touch or with the physical buttons."}, {"icon": "🔋", "title": "13 days of battery in watch mode, 20 h with GPS", "description": "Up to 13 days in smartwatch mode and up to 20 hours in GPS-only mode."}, {"icon": "🛰️", "title": "Multi-band GPS with SatIQ™", "description": "Multi-band GPS is designed for more accurate tracks, including in cities and under trees."}, {"icon": "🏃", "title": "Daily suggested workouts and race predictor", "description": "Workouts suggested each day based on your form, and an estimate of your race times."}, {"icon": "😴", "title": "Recovery, sleep and Body Battery™", "description": "Recovery time, sleep coach, Body Battery™ energy monitoring and nap detection."}, {"icon": "❤️", "title": "Everyday fitness tracking", "description": "Wrist-based heart rate, stress, breathwork, hydration and women’s health. Not a substitute for a medical device."}, {"icon": "📈", "title": "Training load and running dynamics", "description": "Training load (acute load), courses and wrist-based running dynamics."}]$j$::jsonb, $j$[{"question": "What is the battery life?", "answer": "Up to 13 days in smartwatch mode and up to 20 hours in GPS-only mode."}, {"question": "What are its dimensions?", "answer": "The case measures 46.1 × 46.1 × 12.9 mm, with a 1.3-inch (32.5 mm) AMOLED display."}, {"question": "Is it compatible with Garmin Connect and Strava?", "answer": "Yes, it connects to the Garmin Connect app on your phone, which lets you sync your activities with Strava."}, {"question": "Who is this watch for?", "answer": "Runners who want to follow their training and recovery from the wrist: multi-band GPS, suggested workouts, race predictor and training load."}, {"question": "How do delivery and returns work?", "answer": "Delivery times, shipping costs, import charges and return conditions are shown on the offer page and may vary: check them before ordering."}, {"question": "How much does it cost?", "answer": "We do not show prices: they change with offers and coupons. For reference, the listing was at about £286 on 30 October 2026. Compare before you buy."}]$j$::jsonb, '[]'::jsonb, $q$Garmin Forerunner 265: GPS running watch | Tendpick$q$, $q$Garmin Forerunner 265: AMOLED touchscreen, multi-band GPS, suggested workouts and recovery tracking. Specs and highlights.$q$,
